package com.apexbooks.accounting

import androidx.compose.foundation.layout.*
import androidx.compose.material3.*
import androidx.compose.runtime.*
import androidx.compose.ui.Modifier
import androidx.compose.ui.unit.dp
import com.apexbooks.accounting.data.*
import org.json.JSONArray
import org.json.JSONObject
import java.math.BigDecimal

@Composable fun ToolsScreen(vm:AppModel){val required=if(vm.tool.startsWith("recurring"))"recurring_drafts" else if(vm.tool=="reorder")"low_stock_reorder" else if(vm.tool=="attachments")"document_attachments" else "";if(required.isNotBlank()&&!vm.supports(required)){ActionDialog("Server feature availability",vm,confirm="Done",onDismiss={vm.tool=""},onSave={vm.tool=""}){FeatureUpgradeHint(vm)};return};key(vm.companyId,vm.tool){when(vm.tool){"backup"->if(vm.supports("chunked_backups"))CompleteBackupTool(vm)else BasicTool(vm);"restore"->if(vm.supports("chunked_backups"))CompleteBackupTool(vm)else ImportTool(vm);"attachments"->AttachmentsTool(vm);"recurring","recurring_new","recurring_edit","recurring_occurrence"->RecurringTools(vm);"reorder"->ReorderTool(vm);"branding"->BrandingTool(vm);"vyapar","master_import","statement_import"->ImportTool(vm);"journal"->JournalTool(vm);"members"->MembersTool(vm);else->BasicTool(vm)}}}
@Composable private fun ToolInput(values:MutableMap<String,String>,key:String,label:String,number:Boolean=false,password:Boolean=false,multiline:Boolean=false,maximum:Int=500){Field(label,values[key]?:"",{values[key]=it},number=number,password=password,multiline=multiline,maximum=maximum)}

@Composable private fun BasicTool(vm:AppModel){
    val tool=vm.tool;val cid=vm.companyId;val original=vm.toolData;val data=original?.o("data")?:JSONObject()
    val protectedWrite=tool in setOf("transfer","stock_opening","stock_adjust","openings","settle_credit","settle_advance")
    val scope=tool+":"+(original?.s("id")?:"")+":"+(original?.s("source")?:"")
    val draft=remember(cid,scope){vm.toolDraft(scope)}
    // Only financial inputs are retained. Password/recovery inputs remain ephemeral.
    val v=if(protectedWrite)draft.values else remember{mutableStateMapOf<String,String>()}
    var report by remember{mutableStateOf<Any?>(null)};var selected by remember{mutableStateOf("default")};var load by remember{mutableIntStateOf(0)}
    val retry=draft.key;val submission=draft.submission;var unresolved by remember(cid,scope){mutableStateOf(submission.unresolved)}
    fun close(){vm.finishToolDraft(scope);vm.tool="";vm.toolData=null;vm.error=""}
    fun bankChoices()=vm.banks.map{it.s("id") to it.s("name")}
    val sources=vm.records.filter{it.decimal(if(tool=="settle_credit")"credit_remaining"else"advance_remaining")>BigDecimal.ZERO}
    LaunchedEffect(Unit){if(v.isEmpty()){v.putAll(mapOf("date" to today(),"amount" to "","name" to "","number" to "","kind" to "sales_invoice","year" to financialStart().take(4),"balance_kind" to "receivable","party_id" to "","bank_account_id" to (original?.s("bank_account_id")?.ifBlank{null}?:"default"),"to_bank_account_id" to "default","direction" to "cash_to_bank","adjustment" to "increase","category" to "asset","method" to "cash","source" to (original?.s("source")?.takeIf{id->sources.any{it.s("id")==id}}?:sources.firstOrNull()?.s("id")?:""),"action" to "apply","target" to "","format" to "xlsx","export_kind" to "all","from" to financialStart(),"to" to today()));if(original?.s("kind")=="bank_transfer"){for(key in listOf("name","number","date","amount"))v[key]=original.s(key);for(key in listOf("bank_account_id","to_bank_account_id","direction"))if(data.s(key).isNotBlank())v[key]=data.s(key)}}
        try{when(tool){"period"->report=vm.api.request(vm.api.company(cid,"/period-lock"));"prefixes"->report=vm.api.request(vm.api.company(cid,"/number-series"));"audit"->report=vm.api.request(vm.api.company(cid,"/audit-events"));"recovery_saved"->report=original;"cashbook"->Unit}}catch(e:Exception){vm.failure(e)}}
    LaunchedEffect(tool,load){if(tool=="cashbook")try{report=vm.api.request(vm.api.company(cid,"/cash-book?from_date=${v["from"]?:financialStart()}&to_date=${v["to"]?:today()}&bank_account_id=${encode(selected)}"))}catch(e:Exception){vm.failure(e)}}
    val readOnly=tool in setOf("audit","cashbook","recovery_saved")
    val title=mapOf("bank_new" to "Add bank account","transfer" to "Cash and bank transfer","stock_opening" to "Opening stock","stock_adjust" to "Stock adjustment","openings" to "Opening balance","prefixes" to "Transaction prefixes","period" to "Lock accounting period","security" to "Password and sessions","recovery" to "Generate recovery codes","recovery_saved" to "Save your recovery codes","backup" to "Download company backup","data_export" to "Export company data","audit" to "Audit history","ledger_account" to "Add ledger account","reverse_journal" to "Reverse journal","cashbook" to "Cash and bank book","settle_credit" to "Apply or refund note credit","settle_advance" to "Apply or refund advance")[tool]?:friendly(tool)
    ActionDialog(title,vm,unresolved={unresolved},confirm=if(unresolved)"Retry original save"else if(readOnly)"Done"else if(tool in setOf("backup","data_export"))"Download"else if(tool=="period")"Lock through date"else"Save",onDismiss=::close,onSave={
        if(!unresolved && tool in setOf("settle_credit","settle_advance") && sources.none{it.s("id")==v["source"]})throw Exception("Choose an available balance.")
        val submitted=if(protectedWrite)submission.body(JSONObject(v.toMap()))else JSONObject(v.toMap())
        fun value(key:String)=submitted.optString(key,"")
fun root(suffix:String)=vm.api.company(cid,suffix)
        try { when(tool){
            "bank_new"->vm.api.request(root("/bank-accounts"),"POST",JSONObject().put("name",value("name")).put("account_hint",value("account_hint")))
            "transfer"->{val values=JSONObject().put("direction",value("direction")).put("bank_account_id",value("bank_account_id")).put("to_bank_account_id",value("to_bank_account_id"));if(original?.s("kind")=="bank_transfer")values.put("version",data.optInt("version"));vm.api.saveRecord(cid,JSONObject().put("kind","bank_transfer").put("name",value("name").ifBlank{friendly(value("direction"))}).put("number",value("number")).put("date",value("date")).put("amount",value("amount")).put("data",values),retry,if(original?.s("kind")=="bank_transfer")original else null)}
            "stock_opening"->vm.api.request(root("/stock/opening"),"POST",JSONObject().put("item_id",value("item_id")).put("date",value("date")).put("quantity",value("quantity")).put("unit_cost",value("unit_cost")),retry)
            "stock_adjust"->{val body=JSONObject().put("item_id",value("item_id")).put("date",value("date")).put("direction",value("adjustment")).put("quantity",value("quantity")).put("reason",value("reason"));if(value("unit_cost").isNotBlank())body.put("unit_cost",value("unit_cost"));vm.api.request(root("/stock/adjustments"),"POST",body,retry)}
            "openings"->vm.api.request(root("/opening-balances"),"POST",JSONObject().put("kind","opening_balance").put("name","Opening balance").put("date",value("date")).put("amount",value("amount")).put("data",JSONObject().put("balance_kind",value("balance_kind")).put("party_id",value("party_id")).put("bank_account_id",value("bank_account_id")).put("overdraft",value("overdraft")=="true")),retry)
            "prefixes"->vm.api.request(root("/number-series"),"PUT",JSONObject().put("kind",value("kind")).put("financial_year",value("year").toIntOrNull()?:throw Exception("Enter the financial year start." )).put("prefix",value("prefix").uppercase()))
            "period"->vm.api.request(root("/period-lock"),"PUT",JSONObject().put("locked_through",value("date")))
            "ledger_account"->vm.api.request(root("/accounts"),"POST",JSONObject().put("code",value("code")).put("name",value("name")).put("category",value("category")))
            "reverse_journal"->vm.api.request(root("/journals/${original?.s("id")}/reverse"),"POST",JSONObject().put("date",value("date")).put("reference",value("reference")).put("reason",value("reason")))
            "settle_credit","settle_advance"->{val source=sources.find{it.s("id")==value("source")}?:throw Exception("Choose an available balance.");val values=JSONObject().put("action",value("action")).put("applied_to",value("target")).put("payment_account",value("method")).put("bank_account_id",value("bank_account_id"));val endpoint=if(tool=="settle_credit")"/credits/${source.s("id")}/settle"else"/advances/${source.s("id")}/${value("action")}";vm.api.request(root(endpoint),"POST",JSONObject().put("kind","advance_application").put("name",source.s("name")).put("date",value("date")).put("amount",value("amount")).put("data",values),retry)}
            "security"->{vm.api.request("/api/auth/change-password","POST",JSONObject().put("current_password",value("current_password")).put("new_password",value("new_password")));vm.endLocalSession();return@ActionDialog}
            "recovery"->{val result=vm.api.request("/api/auth/recovery-codes","POST",JSONObject().put("current_password",value("current_password")))as JSONObject;vm.toolData=result;vm.tool="recovery_saved";return@ActionDialog}
            "backup"->{val password=value("password");if(password.isNotEmpty()&&password.length<12)throw Exception("Use at least 12 characters.");var bytes=vm.api.bytes(root("/backup"));if(password.isNotBlank())bytes=kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.Default){NativeFiles.encrypt(bytes,password)};vm.files.save(bytes,"apex-${cid.take(8)}-${today()}."+if(password.isBlank())"json.gz"else"apexbackup")}
            "data_export"->{val kind=value("export_kind");val fmt=value("format");val endpoint=when(kind){"all"->"/data-export.json";"reconciliation"->"/imports/vyapar-posting/reconciliation";"archive"->"/imports/vyapar/archive.json";else->"/masters/export.$fmt?kind=$kind"};vm.files.save(vm.api.bytes(root(endpoint)),"apex-$kind."+if(kind in setOf("all","archive","reconciliation"))"json"else fmt)}
        }
        } catch(e:Exception){if(protectedWrite){submission.failed(e);unresolved=submission.unresolved};throw e}
        submission.succeeded();unresolved=false
        close();if(!readOnly&&tool !in setOf("backup","data_export","period","prefixes","security"))vm.refresh()
    }){
        if(unresolved)Message("The previous save may already have posted. Retry original save uses the original values, even if fields were changed. Resolve it before closing or creating a replacement.")
        fun value(key:String)=v[key]?:""
        when(tool){
            "bank_new"->{ToolInput(v,"name","Bank account name");ToolInput(v,"account_hint","Account hint · last digits",maximum=32)}
            "transfer"->{Choice("Direction",value("direction"),listOf("cash_to_bank" to "Cash to bank","bank_to_cash" to "Bank to cash","bank_to_bank" to "Bank to bank"),{v["direction"]=it});Choice(when(value("direction")){"cash_to_bank"->"Deposit into bank";"bank_to_cash"->"Withdraw from bank";else->"From bank"},value("bank_account_id"),bankChoices(),{v["bank_account_id"]=it});if(value("direction")=="bank_to_bank")Choice("To bank",value("to_bank_account_id"),bankChoices(),{v["to_bank_account_id"]=it});DateField("Date",value("date"),{v["date"]=it});ToolInput(v,"amount","Amount (₹)",number=true);ToolInput(v,"name","Description",maximum=120);if(original?.s("kind")=="bank_transfer")ToolInput(v,"number","Reference",maximum=16)}
            "stock_opening","stock_adjust"->{Choice("Item",value("item_id"),listOf("" to "Choose item")+vm.records.filter{it.s("kind")=="item"&&it.o("data").optBoolean("track_stock")&&(tool!="stock_opening"||selectableMaster(it))}.map{it.s("id") to it.s("name")},{v["item_id"]=it});DateField("Date",value("date"),{v["date"]=it});if(tool=="stock_adjust")Choice("Adjustment",value("adjustment"),listOf("increase" to "Increase stock","decrease" to "Decrease stock"),{v["adjustment"]=it});ToolInput(v,"quantity","Quantity",number=true);if(tool=="stock_opening"||value("adjustment")=="increase")ToolInput(v,"unit_cost","Unit cost (₹)",number=true);if(tool=="stock_adjust")ToolInput(v,"reason","Reason",multiline=true)}
            "openings"->{Text("Set openings before the first transaction for this party or account.");Choice("Opening type",value("balance_kind"),listOf("receivable" to "Customer receivable","payable" to "Supplier payable","cash" to "Cash","bank" to "Bank"),{v["balance_kind"]=it});if(value("balance_kind")in setOf("receivable","payable"))Choice("Party",value("party_id"),listOf("" to "Choose party")+vm.records.filter{it.s("kind")=="party"&&selectableMaster(it)}.map{it.s("id") to it.s("name")},{v["party_id"]=it});if(value("balance_kind")=="bank"){Choice("Bank",value("bank_account_id"),bankChoices(),{v["bank_account_id"]=it});Toggle("Bank overdraft",value("overdraft")=="true",{v["overdraft"]=it.toString()})};DateField("Opening date",value("date"),{v["date"]=it});ToolInput(v,"amount","Opening amount (₹)",number=true)}
            "prefixes"->{Choice("Document type",value("kind"),(vm.documentKinds+setOf("payment_in","payment_out")).map{it to friendly(it)},{v["kind"]=it});ToolInput(v,"year","Financial year starting in April",number=true,maximum=4);ToolInput(v,"prefix","Prefix · 1–6 uppercase letters, digits or hyphens",maximum=6);ReportContent(report,"Existing series")}
            "period"->{ReportContent(report);Text("Entries through this date cannot be added or edited. The date can only move forward.");DateField("New lock date",value("date"),{v["date"]=it})}
            "ledger_account"->{ToolInput(v,"code","Account code",maximum=32);ToolInput(v,"name","Account name",maximum=120);Choice("Category",value("category"),listOf("asset","liability","equity","income","expense").map{it to friendly(it)},{v["category"]=it})}
            "reverse_journal"->{Text("The original entry stays in the audit history. This posts an equal opposite journal.");DateField("Reversal date",value("date"),{v["date"]=it});ToolInput(v,"reference","Reversal reference",maximum=80);ToolInput(v,"reason","Reason",multiline=true)}
            "settle_credit","settle_advance"->{if(sources.isEmpty())Text("No available balance.")else{Choice("Available balance",value("source"),sources.map{it.s("id") to "${it.s("number")} · ${it.s("name")} · ${money(it.s(if(tool=="settle_credit")"credit_remaining"else"advance_remaining"))}"},{v["source"]=it;v["target"]="";v["amount"]=""});Choice("Action",value("action"),listOf("apply" to "Apply to invoice / bill","refund" to "Refund"),{v["action"]=it});val source=sources.find{it.s("id")==value("source")};if(value("action")=="apply"){val customer=source?.s("kind")in setOf("payment_in","credit_note");Choice("Invoice / bill",value("target"),listOf("" to "Choose document")+vm.records.filter{it.optBoolean("posted")&&it.s("kind")==if(customer)"sales_invoice"else"purchase_bill"}.filter{it.s("name").trim().equals(source?.s("name")?.trim(),true)&&it.decimal("outstanding")>BigDecimal.ZERO}.map{it.s("id") to "${it.s("number")} · ${money(it.s("outstanding"))} due"},{v["target"]=it})}else{Choice("Refund through",value("method"),listOf("cash" to "Cash","bank" to "Bank / UPI / card"),{v["method"]=it});if(value("method")=="bank")Choice("Bank",value("bank_account_id"),bankChoices(),{v["bank_account_id"]=it})};DateField("Date",value("date"),{v["date"]=it});ToolInput(v,"amount","Amount (₹)",number=true)}}
            "security"->{Text("Changing the password ends all sign-in sessions.");ToolInput(v,"current_password","Current password",password=true,maximum=128);ToolInput(v,"new_password","New password · 8–128 characters",password=true,maximum=128);OutlinedButton(onClick={vm.task{val result=vm.api.request("/api/auth/logout-other-sessions","POST")as JSONObject;vm.notice="${result.s("revoked")} other sessions signed out."}}){Text("Sign out other devices")}}
            "recovery"->{Text("Generating codes replaces previous unused codes. Store the new codes outside this device. Each works once.");ToolInput(v,"current_password","Current password",password=true,maximum=128)}
            "recovery_saved"->{val codes=(0 until (original?.a("codes")?.length()?:0)).joinToString("\n"){original!!.a("codes").getString(it)};Text(codes);OutlinedButton(onClick={vm.files.save(("Apex Books recovery codes\n"+codes).toByteArray(),"apex-recovery-codes.txt")}){Text("Save recovery codes")}}
            "backup"->{Text("Keep your backup and password securely. The password cannot be recovered.");ToolInput(v,"password","Optional password · at least 12 characters",password=true,maximum=128)}
            "data_export"->{Choice("Data",value("export_kind"),listOf("all" to "Full company JSON","party" to "Parties","item" to "Items","reconciliation" to "Vyapar reconciliation","archive" to "Vyapar source archive"),{v["export_kind"]=it});if(value("export_kind")in setOf("party","item"))Choice("Format",value("format"),listOf("xlsx" to "XLSX","csv" to "CSV","pdf" to "PDF"),{v["format"]=it})}
            "audit"->ReportContent(report)
            "cashbook"->{Choice("Bank account · cash included",selected,bankChoices(),{selected=it});DateField("From",value("from"),{v["from"]=it});DateField("To",value("to"),{v["to"]=it});Button(onClick={load++}){Text("Apply dates")};for(fmt in listOf("pdf","xlsx"))OutlinedButton(onClick={vm.task{val bytes=vm.api.bytes(vm.api.company(cid,"/cash-book.$fmt?from_date=${value("from")}&to_date=${value("to")}&bank_account_id=${encode(selected)}"));vm.files.save(bytes,"cash-book.$fmt")}}){Text("Export ${fmt.uppercase()}")};ReportContent(report)}
        }
    }
}
